import { inlineSvg } from "@/lib/inline-svg";

/** Files in public/. `wordmark` is the drawn name at the top of the homepage,
 *  generated by scripts/gen-wordmark.mjs; the two bare names are the homepage
 *  doors; the projects/ ones are the per-card drawings. inlineSvg resolves and
 *  refuses anything outside public/, so the slash here is safe. */
export type FigureName =
  | "wordmark"
  | "blog-backprop"
  | "agent-loop"
  | `projects/${string}`;

/**
 * An SVG from public/, inlined.
 *
 * Server component, no client JS. Everything each file needs is inside it:
 * the wordmark's draw-once animation, and the door figures' static geometry.
 * Colour comes from globals.css, which is only reachable because an inlined
 * svg is not the document root.
 *
 * Each file carries its own <title>/<desc> and role, so nothing is added here.
 */
export function Figure({
  name,
  className,
}: {
  name: FigureName;
  className?: string;
}) {
  return (
    <span
      className={className}
      dangerouslySetInnerHTML={{ __html: inlineSvg(name) }}
    />
  );
}
